import { FormEvent, useState } from 'react';
import { JxAlert, JxButton, JxInputField, JxSelect, JxSwitch } from '@jinx-ui/react';

const roleOptions = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

export default function InviteTeamForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const emailTouched = email.length > 0;
  const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  const emailError = emailTouched && !emailValid ? 'Укажите адрес в формате name@example.com' : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!emailValid) return;
    setSubmitted(true);
  };

  return (
    <form
      onSubmit={submit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r)',
        maxWidth: 420,
      }}
    >
      {submitted && (
        <JxAlert
          intent="success"
          title="Приглашение отправлено"
          onClose={() => setSubmitted(false)}
        >
          Мы отправили приглашение на {email}.
        </JxAlert>
      )}

      <JxInputField
        label="Электронная почта"
        type="email"
        required
        placeholder="name@example.com"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
        helperText="На этот адрес придёт письмо с приглашением"
        errorText={emailError}
      />

      <JxSelect
        label="Роль"
        options={roleOptions}
        value={role}
        onValueChange={setRole}
      />

      <JxSwitch
        label="Отправить уведомление о приглашении"
        checked={notify}
        onChange={(event) => setNotify(event.target.checked)}
      />

      <JxButton type="submit" variant="primary" disabled={!emailValid}>
        Отправить приглашение
      </JxButton>
    </form>
  );
}

